ALTER TABLE public.routes ADD COLUMN journey_minutes integer NOT NULL DEFAULT 30 CHECK(journey_minutes BETWEEN 5 AND 600), ADD COLUMN turnaround_minutes integer NOT NULL DEFAULT 5 CHECK(turnaround_minutes BETWEEN 0 AND 120), ADD COLUMN recovery_percent integer NOT NULL DEFAULT 10 CHECK(recovery_percent BETWEEN 0 AND 100);
ALTER TABLE public.drivers ADD COLUMN route_id uuid REFERENCES public.routes(id) ON DELETE SET NULL;
CREATE OR REPLACE FUNCTION public.validate_operating_assignment() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.route_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.routes r WHERE r.id=NEW.route_id AND r.company_id=NEW.company_id AND r.user_id=NEW.user_id) THEN RAISE EXCEPTION 'Assign a route belonging to this company'; END IF; IF TG_TABLE_NAME='drivers' AND NEW.route_id IS NOT NULL AND NEW.role<>'Driver' THEN RAISE EXCEPTION 'Only drivers can be assigned to bus routes'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_driver_route BEFORE INSERT OR UPDATE ON public.drivers FOR EACH ROW EXECUTE FUNCTION public.validate_operating_assignment();
CREATE TRIGGER validate_bus_route BEFORE INSERT OR UPDATE ON public.buses FOR EACH ROW EXECUTE FUNCTION public.validate_operating_assignment();
CREATE OR REPLACE FUNCTION public.check_operating_fleet_frequency() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE r record; needed integer; crew integer; BEGIN
FOR r IN SELECT rt.*, (SELECT count(*) FROM public.buses b WHERE b.route_id=rt.id AND b.company_id=rt.company_id AND b.status='In service') AS allocated, (SELECT count(*) FROM public.buses b WHERE b.route_id=rt.id AND b.company_id=rt.company_id AND b.status='Broken down') AS broken FROM public.routes rt WHERE rt.company_id=NEW.company_id AND (rt.contract_end_day IS NULL OR rt.contract_end_day>=NEW.day) LOOP
needed=ceil((2*r.journey_minutes+2*r.turnaround_minutes+ceil(2*r.journey_minutes*r.recovery_percent/100.0))/greatest(5,r.frequency_mins));
IF r.allocated+r.broken>0 AND r.allocated<needed THEN RAISE EXCEPTION 'Route % needs % in-service buses; % allocated',r.number,needed,r.allocated; END IF;
SELECT count(*) INTO crew FROM public.drivers WHERE company_id=NEW.company_id AND route_id=r.id AND role='Driver';
IF r.allocated>0 AND crew<r.allocated THEN RAISE EXCEPTION 'Route % needs % assigned drivers; % assigned',r.number,r.allocated,crew; END IF;
END LOOP; RETURN NEW; END $$;
CREATE FUNCTION public.record_bus_breakdowns() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE b record; BEGIN FOR b IN SELECT value FROM jsonb_array_elements(COALESCE(NEW.details->'breakdowns','[]'::jsonb)) LOOP UPDATE public.buses SET status='Broken down' WHERE id=(b.value->>'id')::uuid AND company_id=NEW.company_id AND status='In service'; END LOOP; RETURN NEW; END $$;
CREATE TRIGGER save_bus_breakdowns AFTER INSERT ON public.day_reports FOR EACH ROW EXECUTE FUNCTION public.record_bus_breakdowns();
CREATE FUNCTION public.repair_game_bus(p_company uuid,p_user uuid,p_day integer,p_bus uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.companies; b public.buses; cost integer; BEGIN SELECT * INTO c FROM public.companies WHERE id=p_company AND user_id=p_user AND transport_mode='bus' FOR UPDATE; IF c.id IS NULL OR c.day<>p_day THEN RAISE EXCEPTION 'Company changed; refresh and retry'; END IF; SELECT * INTO b FROM public.buses WHERE id=p_bus AND company_id=c.id AND user_id=p_user FOR UPDATE; IF b.id IS NULL OR b.status<>'Broken down' THEN RAISE EXCEPTION 'This bus does not need a breakdown repair'; END IF; cost=1000+(100-b.condition)*30; IF c.balance<cost THEN RAISE EXCEPTION 'Not enough money'; END IF; UPDATE public.buses SET status='In service',condition=greatest(condition,80) WHERE id=b.id; UPDATE public.companies SET balance=balance-cost WHERE id=c.id; END $$;
REVOKE ALL ON FUNCTION public.repair_game_bus(uuid,uuid,integer,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.repair_game_bus(uuid,uuid,integer,uuid) TO service_role;